assignment.solution:
function fileSizeLabel(bytes) {
  return bytes < 1000 ? "small" : bytes < 1000000 ? "medium" : "large";
}

console.log(fileSizeLabel(500));     // "small"
console.log(fileSizeLabel(50000));   // "medium"
console.log(fileSizeLabel(5000000)); // "large"

